-- Seconds the aura lasts and whether that scales with haste.
function ns.TickDurationFor(spellID)
    if spellID == nil or issecret(spellID) then return nil end
    local raw = ns.TICK_DURATIONS[spellID]
    if not raw then return nil end
    if raw < 0 then return -raw / 1000, true end
    return raw / 1000, false
end

-- Seconds between ticks and whether that scales with haste.
function ns.TickPeriodFor(spellID)
    if spellID == nil or issecret(spellID) then return nil end
    local raw = ns.TICK_PERIODS[spellID]
    if not raw then return nil end
    if raw < 0 then return -raw / 1000, true end
    return raw / 1000, false
end
